import React from "react";
function Syllabs(){
    return(
<div className="flex flex-col items-start relative pt-[62px] pb-9 px-[490px] mb-[178px] mx-[107px] rounded-[28px]" 
	style={{
		background: "linear-gradient(180deg, #0066B2, #002B4C)"
	}}>
	<div className="flex flex-col items-start self-stretch relative">
		<img
			src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/a83zr8d6_expires_30_days.png"} 
			className="self-stretch h-[700px] object-fill"
		/>
		<div className="flex flex-col w-[450px] absolute top-[63px] left-[-336px] rounded-tl-[10px] rounded-bl-[10px] border-[7px] border-solid border-[#00000000]" 
			style={{
				background: "linear-gradient(180deg, #0066B2, #668DA9)"
			}}>
			<span className="text-white text-3xl font-bold text-center mt-[21px] mb-4 mx-[38px]" >
				{"Everyday conversations"}
			</span>
		</div>
		<div className="flex flex-col w-[450px] absolute top-[66px] right-[-360px] rounded-tr-[10px] rounded-br-[10px] border-[7px] border-solid border-[#00000000]" 
			style={{
				background: "linear-gradient(180deg, #668DA9, #0066B2)"
			}}>
			<span className="text-white text-3xl font-bold text-center mt-5 mb-[17px] mx-[45px]" >
				{"Role-playing Dialogues"}
			</span>
		</div>
		<div className="flex flex-col w-[450px] absolute top-[186px] right-[-360px] rounded-tr-[10px] rounded-br-[10px] border-[7px] border-solid border-[#00000000]" 
			style={{
				background: "linear-gradient(180deg, #668DA9, #0066B2)"
			}}>
			<span className="text-white text-3xl font-bold text-center mt-[22px] mb-[21px] mx-[70px]" >
				{"Pronunciation Skills"}
			</span>
		</div>
		<div className="flex flex-col items-start w-[450px] absolute top-[187px] left-[-338px] rounded-tl-[10px] rounded-bl-[10px] border-[7px] border-solid border-[#00000000]" 
			style={{
				background: "linear-gradient(180deg, #0066B2, #668DA9)"
			}}>
			<span className="text-white text-3xl font-bold mt-[21px] mb-4 ml-[108px]" >
				{"Basic  greetings"}
			</span>
        </div>
	</div>
</div>
    );
}
export default Syllabs;
